    starterCode: "import math, random\nrandom.seed(1337)\n\ntext = \"hello world. hello llm. hello neural net. \"\nchars = sorted(set(text))\nV = len(chars)\nstoi = {c: i for i, c in enumerate(chars)}\npairs = [(stoi[text[i]], stoi[text[i + 1]]) for i in range(len(text) - 1)]\n\nH, LR, STEPS = 24, 0.5, 400\n\n# W1: V x H (this doubles as the embedding table), W2: H x V\nW1 = [[random.uniform(-0.5, 0.5) for _ in range(H)] for _ in range(V)]\nW2 = [[random.uniform(-0.5, 0.5) for _ in range(V)] for _ in range(H)]\nb2 = [0.0] * V\n\ndef softmax(xs):\n    m = max(xs)\n    e = [math.exp(x - m) for x in xs]\n    s = sum(e)\n    return [v / s for v in e]\n\nprint(f\"vocab={V}  hidden={H}  params={V * H + H * V + V}  examples={len(pairs)}\")\nprint()\nprint(\" step |   loss  | bits/char\")\nprint(\"------+---------+----------\")\n\nfor step in range(STEPS + 1):\n    total_loss = 0.0\n    gW1 = [[0.0] * H for _ in range(V)]\n    gW2 = [[0.0] * V for _ in range(H)]\n    gb2 = [0.0] * V\n\n    for x, y in pairs:\n        # ---- forward ----\n        h = [math.tanh(W1[x][j]) for j in range(H)]          # one-hot @ W1 = row x\n        logits = [sum(h[j] * W2[j][k] for j in range(H)) + b2[k] for k in range(V)]\n        probs = softmax(logits)\n        total_loss += -math.log(probs[y] + 1e-12)\n\n        # ---- backward ----\n        dlogits = probs[:]                                    # d(CE+softmax)/d(logits)\n        dlogits[y] -= 1.0\n        for k in range(V):\n            gb2[k] += dlogits[k]\n        dh = [0.0] * H\n        for j in range(H):\n            hj = h[j]\n            for k in range(V):\n                gW2[j][k] += hj * dlogits[k]\n                dh[j] += W2[j][k] * dlogits[k]\n        for j in range(H):\n            gW1[x][j] += dh[j] * (1 - h[j] * h[j])            # tanh'\n\n    n = len(pairs)\n    if step % 50 == 0:\n        loss = total_loss / n\n        print(f\" {step:4d} | {loss:7.4f} | {loss / math.log(2):8.4f}\")\n\n    # ---- SGD update ----\n    for i in range(V):\n        for j in range(H):\n            W1[i][j] -= LR * gW1[i][j] / n\n    for j in range(H):\n        for k in range(V):\n            W2[j][k] -= LR * gW2[j][k] / n\n    for k in range(V):\n        b2[k] -= LR * gb2[k] / n\n\nprint()\nprint(\"Loss fell because every weight moved a little way downhill, 400 times.\")\n",
