    starterCode: "import math, random\nrandom.seed(1337)\n\ntext = \"hello world. hello llm. hello neural net. \"\nchars = sorted(set(text))\nV = len(chars)\nstoi = {c: i for i, c in enumerate(chars)}\nitos = {i: c for c, i in stoi.items()}\npairs = [(stoi[text[i]], stoi[text[i + 1]]) for i in range(len(text) - 1)]\n\nH, LR, STEPS = 24, 0.5, 600\nW1 = [[random.uniform(-0.5, 0.5) for _ in range(H)] for _ in range(V)]\nW2 = [[random.uniform(-0.5, 0.5) for _ in range(V)] for _ in range(H)]\nb2 = [0.0] * V\n\ndef softmax(xs, t=1.0):\n    xs = [x / t for x in xs]\n    m = max(xs)\n    e = [math.exp(x - m) for x in xs]\n    s = sum(e)\n    return [v / s for v in e]\n\ndef forward(x, t=1.0):\n    h = [math.tanh(W1[x][j]) for j in range(H)]\n    logits = [sum(h[j] * W2[j][k] for j in range(H)) + b2[k] for k in range(V)]\n    return h, softmax(logits, t)\n\nfor step in range(STEPS):\n    gW1 = [[0.0] * H for _ in range(V)]\n    gW2 = [[0.0] * V for _ in range(H)]\n    gb2 = [0.0] * V\n    for x, y in pairs:\n        h, probs = forward(x)\n        d = probs[:]\n        d[y] -= 1.0\n        dh = [0.0] * H\n        for k in range(V):\n            gb2[k] += d[k]\n        for j in range(H):\n            for k in range(V):\n                gW2[j][k] += h[j] * d[k]\n                dh[j] += W2[j][k] * d[k]\n        for j in range(H):\n            gW1[x][j] += dh[j] * (1 - h[j] * h[j])\n    n = len(pairs)\n    for i in range(V):\n        for j in range(H):\n            W1[i][j] -= LR * gW1[i][j] / n\n    for j in range(H):\n        for k in range(V):\n            W2[j][k] -= LR * gW2[j][k] / n\n    for k in range(V):\n        b2[k] -= LR * gb2[k] / n\n\ndef generate(seed, length, temperature):\n    out = seed\n    x = stoi[seed[-1]]\n    for _ in range(length):\n        _, probs = forward(x, temperature)\n        r, acc = random.random(), 0.0\n        for i, p in enumerate(probs):\n            acc += p\n            if r <= acc:\n                x = i\n                break\n        out += itos[x]\n    return out\n\n_, probs = forward(stoi[\"h\"])\nranked = sorted(zip(chars, probs), key=lambda cp: -cp[1])[:5]\nprint(\"after 'h', the model predicts:\")\nfor c, p in ranked:\n    bar = \"#\" * int(p * 40)\n    print(f\"  {repr(c):>5} {p:6.1%} {bar}\")\n\nprint()\nfor t in (0.4, 0.8, 1.5):\n    print(f\"T={t}: {generate('h', 44, t)!r}\")\n",
    expectedOutput: "after 'h', the model predicts:\n    'e'  99.7% #######################################\n    '.'   0.1% \n    'r'   0.1% \n    'h'   0.0% \n    'n'   0.0% \n\nT=0.4: 'helorlo hellllo hellllo helllo wo hellllo hel'\nT=0.8: 'held. het. nello net. helllm. heurallo helo w'\nT=1.5: 'helo heuralo neld. neurld. helmloralll rallo '",
